const DEMO_ASSET_BASE = new URL('assets/', document.currentScript?.src || document.baseURI).href;
(function () {
  const key = 'form-earth-bag';
  const allowedVariants = ['Studio finish', 'Deep cobalt', 'Chalk interior', 'Speckled clay', 'Clear glaze', 'Ash wash', 'Raw porcelain', 'Cobalt line', 'Quiet edge'];
  const products = {
    'cobalt-vase': { name:'Cobalt Vessel 04', price:280, image:DEMO_ASSET_BASE + 'studio-vase.jpg', detail:'Wheel-thrown stoneware vessel with a deep cobalt glaze.', material:'Stoneware, cobalt glaze', dimensions:'28 × 12 cm', variants:['Deep cobalt','Chalk interior'], stock:'Available in this demo' },
    'slab-bowl': { name:'Slab Bowl 02', price:145, image:DEMO_ASSET_BASE + 'studio-bowl.jpg', detail:'Hand-built serving bowl with a softly folded rim.', material:'Speckled stoneware', dimensions:'22 × 6 cm', variants:['Speckled clay','Clear glaze'], stock:'Available in this demo' },
    'ash-cup': { name:'Ash Cup 01', price:68, image:DEMO_ASSET_BASE + 'studio-cup.jpg', detail:'A handleless drinking cup with a deep cobalt glaze and an unglazed foot.', material:'Stoneware, cobalt glaze', dimensions:'8 × 8 cm', variants:['Ash wash','Raw porcelain'], stock:'Low studio quantity' },
    'signal-plate': { name:'Signal Plate 03', price:96, image:DEMO_ASSET_BASE + 'studio-hero.jpg', detail:'A broad, low plate with a gently irregular rim and speckled chalk glaze.', material:'Speckled white stoneware', dimensions:'24 × 2 cm', variants:['Cobalt line','Quiet edge'], stock:'Available in this demo' }
  };
  const image = DEMO_ASSET_BASE + 'studio-hero.jpg';
  const valid = value => typeof value === 'string' && allowedVariants.includes(value) ? value : 'Studio finish';
  const clean = raw => { if (!Array.isArray(raw)) return []; return raw.filter(item => item && products[item.id]).map(item => ({ id:item.id, variant:valid(item.variant), qty:Math.max(1, Math.min(20, Math.floor(Number(item.qty) || 1))) })); };
  let storageUnavailable = false;
  const readBag = () => { try { return clean(JSON.parse(localStorage.getItem(key) || '[]')); } catch (_) { storageUnavailable = true; return []; } };
  const saveBag = bag => { try { localStorage.setItem(key, JSON.stringify(clean(bag))); storageUnavailable = false; } catch (_) { storageUnavailable = true; } updateCount(); showStorageError(); };
  const showStorageError = () => { document.querySelectorAll('[data-storage-error]').forEach(el => { el.hidden = !storageUnavailable; }); };
  const updateCount = () => { const n = readBag().reduce((sum, item) => sum + item.qty, 0); document.querySelectorAll('[data-bag-count]').forEach(el => el.textContent = n); };
  const add = (id, qty, variant) => { if (!products[id]) return; const bag = readBag(); const cleanVariant = valid(variant); const found = bag.find(item => item.id === id && item.variant === cleanVariant); if (found) found.qty = Math.min(20, found.qty + qty); else bag.push({ id, qty:Math.min(20, Math.max(1, qty)), variant:cleanVariant }); saveBag(bag); };
  const renderBag = () => { const host = document.querySelector('[data-bag-items]'); if (!host) return; const bag = readBag(); const empty = document.querySelector('[data-empty]'); const summary = document.querySelector('[data-summary]'); host.replaceChildren(); if (!bag.length) { empty.hidden = false; summary.hidden = true; showStorageError(); return; } empty.hidden = true; summary.hidden = false; bag.forEach(item => { const p = products[item.id]; const article = document.createElement('article'); article.className = 'bag-item'; const img = document.createElement('img'); img.src = p.image; img.alt = `${p.name} studio image`; const body = document.createElement('div'); const title = document.createElement('h2'); title.textContent = p.name; const meta = document.createElement('div'); meta.className = 'product-meta'; meta.textContent = `${item.variant} · ${p.material}`; const controls = document.createElement('div'); controls.className = 'bag-controls'; const qty = document.createElement('input'); qty.type = 'number'; qty.min = '1'; qty.max = '20'; qty.value = item.qty; qty.setAttribute('aria-label', `Quantity for ${p.name}`); qty.addEventListener('change', () => { const next = readBag(); const found = next.find(row => row.id === item.id && row.variant === item.variant); if (found) found.qty = Math.max(1, Math.min(20, Math.floor(Number(qty.value) || 1))); saveBag(next); renderBag(); }); const remove = document.createElement('button'); remove.className = 'remove'; remove.type = 'button'; remove.textContent = 'Remove'; remove.addEventListener('click', () => { saveBag(readBag().filter(row => !(row.id === item.id && row.variant === item.variant))); renderBag(); }); controls.append(qty, remove); body.append(title, meta, controls); const amount = document.createElement('strong'); amount.textContent = `€${(p.price * item.qty).toLocaleString('en-IE')}`; article.append(img, body, amount); host.append(article); }); const total = bag.reduce((sum, item) => sum + products[item.id].price * item.qty, 0); document.querySelector('[data-subtotal]').textContent = `€${total.toLocaleString('en-IE')}`; document.querySelector('[data-total]').textContent = `€${total.toLocaleString('en-IE')}`; showStorageError(); };
  const hydrateObject = () => { const title = document.querySelector('.detail-copy h1'); if (!title) return; const id = new URLSearchParams(location.search).get('item') || 'cobalt-vase'; const p = products[id] || products['cobalt-vase']; document.title = `${p.name} | FORM / EARTH`; title.textContent = p.name; document.querySelector('.detail-price').textContent = `€${p.price}`; document.querySelector('.lede').textContent = p.detail; const specs = document.querySelectorAll('.spec-row span:last-child'); specs[0].textContent = p.dimensions; specs[1].textContent = p.material; document.querySelectorAll('.detail-media img').forEach(img => { img.src = p.image || image; img.alt = `${p.name} studio image`; }); document.querySelectorAll('[data-variant]').forEach((button, index) => { button.textContent = p.variants[index] || p.variants[0]; button.setAttribute('aria-pressed', index === 0 ? 'true' : 'false'); button.classList.toggle('active', index === 0); }); const stock = document.querySelector('.stock'); if (stock) stock.textContent = p.stock; const addButton = document.querySelector('[data-add]'); if (addButton) addButton.dataset.add = id; };
  const wire = () => { hydrateObject(); updateCount(); renderBag(); document.querySelectorAll('[data-add]').forEach(btn => btn.addEventListener('click', () => { const qty = Math.max(1, Math.min(20, Number(document.querySelector('[data-qty]')?.value || 1))); const variant = document.querySelector('[data-variant].active')?.textContent || 'Studio finish'; add(btn.dataset.add, qty, variant); btn.textContent = 'Added to bag'; const live = document.querySelector('[data-live]'); if (live) live.textContent = 'Added to bag'; setTimeout(() => { btn.textContent = 'Add to bag'; }, 1400); })); document.querySelectorAll('[data-variant]').forEach(btn => btn.addEventListener('click', () => { document.querySelectorAll('[data-variant]').forEach(v => { v.classList.remove('active'); v.setAttribute('aria-pressed', 'false'); }); btn.classList.add('active'); btn.setAttribute('aria-pressed', 'true'); })); document.querySelectorAll('[data-qty-step]').forEach(btn => btn.addEventListener('click', () => { const input = document.querySelector('[data-qty]'); input.value = Math.max(1, Math.min(20, Number(input.value) + Number(btn.dataset.qtyStep))); })); const checkout = document.querySelector('[data-checkout]'); if (checkout) checkout.addEventListener('click', () => { document.querySelector('[data-notice]').classList.add('show'); checkout.textContent = 'Demo checkout complete'; checkout.disabled = true; }); showStorageError(); };
  document.addEventListener('DOMContentLoaded', wire);
  window.FORM_EARTH = { products, add };
})();
